require_once __DIR__ . '/includes/functions.php'; $u=require_role('business_owner'); $pdo=db(); $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $date=$_POST['activity_date']??date('Y-m-d'); $type=$_POST['activity_type']??'sale'; $desc=trim($_POST['description']??''); $amount=(float)($_POST['amount']??0); $proof=trim($_POST['evidence_note']??''); if ($desc===''||$amount<0||!in_array($type,['sale','expense','purchase','invoice','other'],true)) $error=t('Please provide a description, valid type and non-negative amount.','Saisissez une description, un type valide et un montant positif ou nul.'); else { $s=$pdo->prepare('INSERT INTO business_activity (user_id,activity_date,activity_type,description,amount,evidence_note) VALUES (?,?,?,?,?,?)');$s->execute([$u['id'],$date,$type,$desc,$amount,$proof?:null]);$s=$pdo->prepare('INSERT INTO readiness_history (user_id,readiness_score) VALUES (?,?)');$s->execute([$u['id'],readiness_data((int)$u['id'])['score']]);flash('success',t('Business activity recorded.','Activité commerciale enregistrée.'));redirect('activity.php'); } }
$s=$pdo->prepare('SELECT * FROM business_activity WHERE user_id=? ORDER BY activity_date DESC,id DESC');$s->execute([$u['id']]);$rows=$s->fetchAll();$pageTitle=t('Business activity','Activité commerciale');require __DIR__.'/includes/header.php';
?>
<div class="dashboard-heading"><div><span class="eyebrow"><?= e(t('BUSINESS RECORDS','REGISTRES COMMERCIAUX')) ?></span><h1><?= e(t('Record your activity','Enregistrer votre activité')) ?></h1><p><?= e(t('Simple records count. Start with the sales, purchases and expenses you can remember.','Des registres simples sont utiles. Commencez par les ventes, achats et dépenses dont vous vous souvenez.')) ?></p></div><a class="btn btn-outline" href="<?= e(url('dashboard.php')) ?>">← <?= e(t('Dashboard','Tableau de bord')) ?></a></div>
<div class="content-two-col"><form class="panel form-card-inner" method="post"><h2><?= e(t('Add a record','Ajouter un enregistrement')) ?></h2><?php if($error): ?><div class="alert alert-error"><?= e($error) ?></div><?php endif; ?><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label><?= e(t('Date','Date')) ?><input type="date" name="activity_date" value="<?= e($_POST['activity_date']??date('Y-m-d')) ?>" required></label><label><?= e(t('Activity type','Type d’activité')) ?><select name="activity_type"><?php foreach(['sale'=>['Sale / revenue','Vente / revenu'],'expense'=>['Expense','Dépense'],'purchase'=>['Purchase / stock','Achat / stock'],'invoice'=>['Invoice issued','Facture émise'],'other'=>['Other','Autre']] as $v=>$l): ?><option value="<?= e($v) ?>"><?= e(t($l[0],$l[1])) ?></option><?php endforeach; ?></select></label><label><?= e(t('Description','Description')) ?><input name="description" placeholder="<?= e(t('e.g. Market sales, fabric purchase','ex. ventes au marché, achat de tissu')) ?>" required></label><label><?= e(t('Amount (XAF)','Montant (FCFA)')) ?><input type="number" name="amount" min="0" step="1" required></label><label><?= e(t('Evidence note (optional)','Note justificative (facultatif)')) ?><textarea name="evidence_note" rows="3" placeholder="<?= e(t('Receipt, mobile money reference, notebook entry…','Reçu, référence Mobile Money, note de cahier…')) ?>"></textarea></label><button class="btn btn-primary full-width" type="submit"><?= e(t('Save record','Enregistrer')) ?></button><p class="fine-print"><?= e(t('Only enter information you are comfortable storing. Never enter PINs or passwords for banking or mobile money services.','Ne saisissez que les informations que vous acceptez de conserver. Ne saisissez jamais de code PIN ni de mot de passe bancaire ou Mobile Money.')) ?></p></form>
<section class="panel"><div class="panel-heading"><h2><?= e(t('Your records','Vos enregistrements')) ?></h2><span class="pill pill-blue"><?= count($rows) ?> <?= e(t('entries','entrées')) ?></span></div><?php if(!$rows): ?><p class="empty-state"><?= e(t('No activity yet. Add your first record on the left.','Aucune activité pour le moment. Ajoutez votre premier enregistrement à gauche.')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(t('Date','Date')) ?></th><th><?= e(t('Description','Description')) ?></th><th><?= e(t('Type','Type')) ?></th><th><?= e(t('Amount','Montant')) ?></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['activity_date']) ?></td><td><?= e($r['description']) ?><?php if($r['evidence_note']): ?><small class="table-sub"><?= e($r['evidence_note']) ?></small><?php endif; ?></td><td><?= e(t(ucfirst($r['activity_type']),['sale'=>'Vente','expense'=>'Dépense','purchase'=>'Achat','invoice'=>'Facture','other'=>'Autre'][$r['activity_type']]??ucfirst($r['activity_type']))) ?></td><td><?= e(number_format((float)$r['amount'],0)) ?> XAF</td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
